import numpy as np

def is_polar(bonds):
    """True if the bond dipoles (direction, size) do not add up to zero."""
    total = np.zeros(3)
    for direction, size in bonds:
        d = np.asarray(direction, dtype=float)
        total += size * d / np.linalg.norm(d)
    return bool(np.linalg.norm(total) > 1e-6)
